  "extracted_concepts": [
    {
      "name": "Sample Space",
      "aliases": [
        "Sample Space",
        "样本空间"
      ],
      "definition_snippet": "Set Ω of all possible outcomes of a random experiment.",
      "category": "concept"
    },
    {
      "name": "Event",
      "aliases": [
        "Event",
        "事件"
      ],
      "definition_snippet": "Subset of a sample space.",
      "category": "concept"
    },
    {
      "name": "Probability Axioms",
      "aliases": [
        "Probability Axioms",
        "概率公理"
      ],
      "definition_snippet": "Rules P(A)≥0, P(Ω)=1, countable additivity.",
      "category": "property"
    },
    {
      "name": "Countable Additivity",
      "aliases": [
        "Countable Additivity",
        "可数可加性"
      ],
      "definition_snippet": "Probability of disjoint union equals sum of probabilities.",
      "category": "property"
    },
    {
      "name": "Classical Probability Model",
      "aliases": [
        "Classical Probability Model",
        "古典概率模型"
      ],
      "definition_snippet": "P(A)=|A|/|Ω| for equally likely outcomes.",
      "category": "concept"
    },
    {
      "name": "Conditional Probability",
      "aliases": [
        "Conditional Probability",
        "条件概率"
      ],
      "definition_snippet": "P(B|A)=P(AB)/P(A).",
      "category": "operation"
    },
    {
      "name": "Bayes' Theorem",
      "aliases": [
        "Bayes' Theorem",
        "贝叶斯定理"
      ],
      "definition_snippet": "Updates posterior probabilities from likelihoods.",
      "category": "theorem"
    },
    {
      "name": "Independence",
      "aliases": [
        "Independence",
        "独立性"
      ],
      "definition_snippet": "P(AB)=P(A)P(B).",
      "category": "property"
    },
    {
      "name": "Random Variable",
      "aliases": [
        "Random Variable",
        "随机变量"
      ],
      "definition_snippet": "Function X:Ω→ℝ assigning numbers to outcomes.",
      "category": "concept"
    },
    {
      "name": "Probability Mass Function",
      "aliases": [
        "Probability Mass Function",
        "概率质量函数"
      ],
      "definition_snippet": "P(X=x_k)=p_k for discrete random variables.",
      "category": "concept"
    },
    {
      "name": "Binomial Distribution",
      "aliases": [
        "Binomial Distribution",
        "二项分布"
      ],
      "definition_snippet": "Discrete distribution B(n,p) for binomial trials.",
      "category": "concept"
    },
    {
      "name": "Poisson Distribution",
      "aliases": [
        "Poisson Distribution",
        "泊松分布"
      ],
      "definition_snippet": "Discrete distribution P(λ) for counts.",
      "category": "concept"
    },
    {
      "name": "Probability Density Function",
      "aliases": [
        "Probability Density Function",
        "概率密度函数"
      ],
      "definition_snippet": "Nonnegative f with integral 1 for continuous variables.",
      "category": "concept"
    },
    {
      "name": "Cumulative Distribution Function",
      "aliases": [
        "Cumulative Distribution Function",
        "累积分布函数"
      ],
      "definition_snippet": "F(x)=P(X≤x).",
      "category": "concept"
    },
    {
      "name": "Normal Distribution",
      "aliases": [
        "Normal Distribution",
        "正态分布"
      ],
      "definition_snippet": "Continuous distribution N(μ,σ²).",
      "category": "concept"
    },
    {
      "name": "Function of Random Variables",
      "aliases": [
        "Function of Random Variables",
        "随机变量函数"
      ],
      "definition_snippet": "Distribution of Y=g(X) via CDF or transformation.",
      "category": "operation"
    },
    {
      "name": "Joint Distribution",
      "aliases": [
        "Joint Distribution",
        "联合分布"
      ],
      "definition_snippet": "F(x,y)=P(X≤x,Y≤y) or joint density.",
      "category": "concept"
    },
    {
      "name": "Marginal Distribution",
      "aliases": [
        "Marginal Distribution",
        "边缘分布"
      ],
      "definition_snippet": "Distribution of one variable obtained by integrating joint density.",
      "category": "concept"
    },
    {
      "name": "Convolution",
      "aliases": [
        "Convolution",
        "卷积"
      ],
