      "category": "operation"
    },
    {
      "name": "Variance",
      "aliases": [
        "Variance",
        "方差"
      ],
      "definition_snippet": "Var(X)=E(X²)-[E(X)]².",
      "category": "operation"
    },
    {
      "name": "Covariance",
      "aliases": [
        "Covariance",
        "协方差"
      ],
      "definition_snippet": "Cov(X,Y)=E(XY)-E(X)E(Y).",
