    },
    {
      "name": "Unbiasedness",
      "aliases": [
        "Unbiasedness",
        "无偏性"
      ],
      "definition_snippet": "E(θ̂)=θ.",
      "category": "property"
    },
    {
      "name": "Consistency",
      "aliases": [
        "Consistency",
        "相合性"
      ],
      "definition_snippet": "θ̂→^P θ as n grows.",
      "category": "property"
    },
    {
      "name": "Confidence Interval",
