      "category": "concept"
    },
    {
      "name": "Rejection Region",
      "aliases": [
        "Rejection Region",
        "拒绝域"
      ],
      "definition_snippet": "Set of statistic values leading to rejecting H0.",
      "category": "concept"
    },
    {
      "name": "Significance Level",
      "aliases": [
        "Significance Level",
        "显著性水平"
      ],
      "definition_snippet": "Probability of Type I error, α.",
      "category": "concept"
    }
